// Collect server-side logs for browser console output instead of server-side error_log
$client_console_logs = [];
function client_console_log($msg, $level = 'error')
{
    global $client_console_logs;
    if (!is_string($msg))
        $msg = print_r($msg, true);
    $msg = preg_replace('/(Authorization:\s*Bearer\s+)[^\s\\\]]+/i', '$1[REDACTED]', $msg);
    $msg = preg_replace('/(access_token|refresh_token|api_key|apiKey)["\']?\s*[:=]\s*[^\s\,\)\}]+/i', '$1: [REDACTED]', $msg);
    $msg = mb_substr($msg, 0, 2000);
    $client_console_logs[] = ['level' => $level, 'msg' => $msg];
}

// Token cache path
$tokenCacheFile = '/var/www/cache/tokens/start_bot_tokens.json';

function ensureTokenCacheDirExists($filePath)
{
    $dir = dirname($filePath);
    if (!is_dir($dir)) {
        @mkdir($dir, 0755, true);
    }
}

function readTokenCacheFile($filePath)
{
    if (!file_exists($filePath))
        return [];
    $contents = @file_get_contents($filePath);
    if ($contents === false)
        return [];
    $data = json_decode($contents, true);
    return is_array($data) ? $data : [];
}

function writeTokenCacheFile($filePath, $data)
{
    ensureTokenCacheDirExists($filePath);
    $tmp = $filePath . '.tmp';
    $json = json_encode($data, JSON_PRETTY_PRINT);
    if (@file_put_contents($tmp, $json, LOCK_EX) === false)
        return false;
    return @rename($tmp, $filePath);
}

function getTokenCacheEntry($filePath, $twitchId)
{
    $cache = readTokenCacheFile($filePath);
    return $cache[$twitchId] ?? null;
}

function setTokenCacheEntry($filePath, $twitchId, $entry)
{
    $cache = readTokenCacheFile($filePath);
    $cache[$twitchId] = $entry;
    return writeTokenCacheFile($filePath, $cache);
}

function removeTokenCacheEntry($filePath, $twitchId)
{
    $cache = readTokenCacheFile($filePath);
    if (isset($cache[$twitchId])) {
        unset($cache[$twitchId]);
        return writeTokenCacheFile($filePath, $cache);
    }
    return true;
}

function admin_start_bots_twitch_validate($accessToken)
{
    $accessToken = trim((string) $accessToken);
    if ($accessToken === '') {
        return ['ok' => false, 'expires_in' => 0];
    }
    $ch = curl_init('https://id.twitch.tv/oauth2/validate');
    if (!$ch) {
        return ['ok' => false, 'expires_in' => 0];
    }
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_TIMEOUT, 10);
    curl_setopt($ch, CURLOPT_HTTPHEADER, ['Authorization: OAuth ' . $accessToken]);
    $response = curl_exec($ch);
    $httpCode = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    if ($httpCode !== 200) {
        return ['ok' => false, 'expires_in' => 0];
    }
    $data = json_decode((string) $response, true);
    if (!is_array($data)) {
        return ['ok' => false, 'expires_in' => 0];
    }
    return ['ok' => true, 'expires_in' => (int) ($data['expires_in'] ?? 0)];
}

function admin_start_bots_load_token_pair($conn, $twitchUserId)
{
    $empty = ['login_access' => '', 'refresh' => '', 'bot_access' => ''];
    if (!$conn || $twitchUserId === '') {
        return $empty;
    }
    $stmt = $conn->prepare(
        'SELECT u.access_token, u.refresh_token, tba.twitch_access_token
         FROM users u
         LEFT JOIN twitch_bot_access tba ON tba.twitch_user_id = u.twitch_user_id
         WHERE u.twitch_user_id = ? LIMIT 1'
    );
    if (!$stmt) {
        return $empty;
    }
    $stmt->bind_param('s', $twitchUserId);
    if (!$stmt->execute()) {
        $stmt->close();
        return $empty;
    }
    $res = $stmt->get_result();
    $row = $res ? $res->fetch_assoc() : null;
    $stmt->close();
    if (!$row) {
        return $empty;
    }
    return [
        'login_access' => trim((string) ($row['access_token'] ?? '')),
        'refresh' => trim((string) ($row['refresh_token'] ?? '')),
        'bot_access' => trim((string) ($row['twitch_access_token'] ?? '')),
    ];
}

function admin_start_bots_refresh_grant($clientId, $clientSecret, $refreshToken)
{
    $refreshToken = trim((string) $refreshToken);
    if ($refreshToken === '' || $clientId === '' || $clientSecret === '') {
        return ['ok' => false];
    }
    $ch = curl_init('https://id.twitch.tv/oauth2/token');
    if (!$ch) {
        return ['ok' => false];
    }
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
        'grant_type' => 'refresh_token',
        'refresh_token' => $refreshToken,
    ]));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_TIMEOUT, 10);
    $response = curl_exec($ch);
    $httpCode = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    if ($httpCode !== 200) {
        return ['ok' => false];
    }
    $data = json_decode((string) $response, true);
    $access = is_array($data) ? trim((string) ($data['access_token'] ?? '')) : '';
    if ($access === '') {
        return ['ok' => false];
    }
    return [
        'ok' => true,
        'access_token' => $access,
        'refresh_token' => trim((string) ($data['refresh_token'] ?? $refreshToken)),
        'expires_in' => (int) ($data['expires_in'] ?? 0),
    ];
}

function admin_start_bots_write_login_token($conn, $twitchUserId, $accessToken, $refreshToken = null)
{
    $accessToken = trim((string) $accessToken);
    $twitchUserId = trim((string) $twitchUserId);
    if ($accessToken === '' || $twitchUserId === '' || !$conn) {
        return false;
    }
    if ($refreshToken !== null && $refreshToken !== '') {
        $stmt = $conn->prepare('UPDATE users SET access_token = ?, refresh_token = ? WHERE twitch_user_id = ? LIMIT 1');
        if (!$stmt) {
            return false;
        }
        $stmt->bind_param('sss', $accessToken, $refreshToken, $twitchUserId);
    } else {
        $stmt = $conn->prepare('UPDATE users SET access_token = ? WHERE twitch_user_id = ? LIMIT 1');
        if (!$stmt) {
            return false;
        }
        $stmt->bind_param('ss', $accessToken, $twitchUserId);
    }
    $ok = $stmt->execute();
    $stmt->close();
    return $ok;
}

function admin_start_bots_write_bot_token($conn, $twitchUserId, $accessToken)
{
    $accessToken = trim((string) $accessToken);
    $twitchUserId = trim((string) $twitchUserId);
    if ($accessToken === '' || $twitchUserId === '' || !$conn) {
        return false;
    }
    $stmt = $conn->prepare('INSERT INTO twitch_bot_access (twitch_user_id, twitch_access_token) VALUES (?, ?) ON DUPLICATE KEY UPDATE twitch_access_token = VALUES(twitch_access_token)');
    if (!$stmt) {
        return false;
    }
    $stmt->bind_param('ss', $twitchUserId, $accessToken);
    $ok = $stmt->execute();
    $stmt->close();
    return $ok;
}

function admin_start_bots_write_refresh_token($conn, $twitchUserId, $refreshToken)
{
    $refreshToken = trim((string) $refreshToken);
    $twitchUserId = trim((string) $twitchUserId);
    if ($refreshToken === '' || $twitchUserId === '' || !$conn) {
        return false;
    }
    $stmt = $conn->prepare('UPDATE users SET refresh_token = ? WHERE twitch_user_id = ? LIMIT 1');
    if (!$stmt) {
        return false;
    }
    $stmt->bind_param('ss', $refreshToken, $twitchUserId);
    $ok = $stmt->execute();
    $stmt->close();
    return $ok;
}

// Login/start = users.access_token. Bot/API = twitch_bot_access. Repair only the dead store.
function admin_start_bots_ensure_token_pair($conn, $twitchUserId, $clientId, $clientSecret)
{
    $pair = admin_start_bots_load_token_pair($conn, $twitchUserId);
    $loginCheck = admin_start_bots_twitch_validate($pair['login_access']);
    $botCheck = admin_start_bots_twitch_validate($pair['bot_access']);
    $loginOk = !empty($loginCheck['ok']);
    $botOk = !empty($botCheck['ok']);
    $repaired = [];

    if ((!$loginOk || !$botOk) && $pair['refresh'] !== '') {
        $refreshed = admin_start_bots_refresh_grant($clientId, $clientSecret, $pair['refresh']);
        if (!empty($refreshed['ok'])) {
            $newAccess = $refreshed['access_token'];
            $newRefresh = $refreshed['refresh_token'];
            if ($newRefresh !== '' && $newRefresh !== $pair['refresh']) {
                admin_start_bots_write_refresh_token($conn, $twitchUserId, $newRefresh);
                $pair['refresh'] = $newRefresh;
            }
            if (!$loginOk) {
                admin_start_bots_write_login_token($conn, $twitchUserId, $newAccess, $pair['refresh']);
                $pair['login_access'] = $newAccess;
                $loginCheck = ['ok' => true, 'expires_in' => (int) ($refreshed['expires_in'] ?? 0)];
                $loginOk = true;
                $repaired[] = 'login';
            }
            if (!$botOk) {
                admin_start_bots_write_bot_token($conn, $twitchUserId, $newAccess);
                $pair['bot_access'] = $newAccess;
                $botCheck = ['ok' => true, 'expires_in' => (int) ($refreshed['expires_in'] ?? 0)];
                $botOk = true;
                $repaired[] = 'bot';
            }
        }
    }

    if (!$loginOk && !$botOk) {
        $message = t('admin_start_bots_token_both_invalid');
    } elseif (!$loginOk) {
        $message = t('admin_start_bots_token_login_invalid');
    } elseif (!$botOk) {
        $message = t('admin_start_bots_token_bot_invalid');
    } else {
        $message = t('admin_start_bots_token_both_valid');
    }

    $loginExpires = $loginOk ? (int) ($loginCheck['expires_in'] ?? 0) : 0;
    $botExpires = $botOk ? (int) ($botCheck['expires_in'] ?? 0) : 0;
    $expiresIn = 0;
    if ($loginOk && $botOk) {
        $expiresIn = min($loginExpires, $botExpires);
    }

    return [
        'ok' => $loginOk && $botOk,
        'login_valid' => $loginOk,
        'bot_valid' => $botOk,
        'login_expires_in' => $loginExpires,
        'bot_expires_in' => $botExpires,
        'expires_in' => $expiresIn,
        'login_token' => $pair['login_access'],
        'bot_token' => $pair['bot_access'],
        'repaired' => $repaired,
        'message' => $message,
    ];
}

function get_admin_beta_mode_params($conn, $channelLookupId, $useCustom = false, $useSelf = false, $legacyTwitchUserId = null) {
    $params = [
        'use_custom_bot' => false,
        'custom_bot_username' => null,
        'use_self' => (bool) $useSelf
    ];
    if (!$useCustom || empty($channelLookupId)) {
        return $params;
    }
    $stmt = $conn->prepare("SELECT bot_username, is_verified FROM custom_bots WHERE channel_id = ? LIMIT 1");
    if (!$stmt) {
        client_console_log('get_admin_beta_mode_params: failed to prepare custom_bots lookup', 'warn');
        return $params;
    }
    $lookupId = (string) $channelLookupId;
    $stmt->bind_param('s', $lookupId);
    $stmt->execute();
    $res = $stmt->get_result();
    $row = $res ? $res->fetch_assoc() : null;
    $stmt->close();
    if (!$row && !empty($legacyTwitchUserId)) {
        $stmtLegacy = $conn->prepare("SELECT bot_username, is_verified FROM custom_bots WHERE channel_id = ? LIMIT 1");
        if ($stmtLegacy) {
            $legacyLookupId = (string) $legacyTwitchUserId;
            $stmtLegacy->bind_param('s', $legacyLookupId);
            $stmtLegacy->execute();
            $legacyRes = $stmtLegacy->get_result();
            $row = $legacyRes ? $legacyRes->fetch_assoc() : null;
            $stmtLegacy->close();
        }
    }
    if (!$row) {
        client_console_log('get_admin_beta_mode_params: no custom bot record for channel_id=' . $lookupId, 'warn');
        return $params;
    }
    if ((int) ($row['is_verified'] ?? 0) !== 1) {
        client_console_log('get_admin_beta_mode_params: custom bot exists but is not verified for channel_id=' . $lookupId, 'warn');
        return $params;
    }
    $customBotUsername = trim((string) ($row['bot_username'] ?? ''));
    if ($customBotUsername === '') {
        client_console_log('get_admin_beta_mode_params: custom bot username is empty for channel_id=' . $lookupId, 'warn');
        return $params;
    }
    $params['use_custom_bot'] = true;
    $params['custom_bot_username'] = $customBotUsername;
    $params['use_self'] = false;
    return $params;
}

// $forceCustom: true = start stable/beta as the verified custom bot, false = do not,
// null = previous behaviour (stable/beta follow the user's saved use_custom flag).
function admin_start_mode_params($conn, $botType, $userId, $twitchUserId, $useCustomFromDb, $useSelfFromDb, $forceCustom) {
    $actionBotType = ($botType === 'custom') ? 'beta' : $botType;
    $wantCustom = ($botType === 'custom')
        || $forceCustom === true
        || ($forceCustom === null && $useCustomFromDb && in_array($actionBotType, ['stable', 'beta'], true));
    $params = [
        '_action_bot_type' => $actionBotType,
        '_error' => null,
        'use_custom_bot' => false,
        'custom_bot_username' => null,
        'use_self' => false,
    ];
    if ($wantCustom && in_array($actionBotType, ['stable', 'beta'], true)) {
        $customParams = get_admin_beta_mode_params($conn, $userId, true, false, $twitchUserId);
        if (empty($customParams['use_custom_bot'])) {
            $params['_error'] = t('admin_start_bots_err_custom_not_verified');
            return $params;
        }
        $params = array_merge($params, $customParams);
        $params['use_self'] = false;
        return $params;
    }
    if (in_array($actionBotType, ['stable', 'beta'], true) && $useSelfFromDb && $forceCustom !== true) {
        $params['use_self'] = true;
    }
    return $params;
}

// Lightweight wrapper to provide a start_bot_for_user() function when missing.
// This uses the central performBotAction() implementation in dashboard/bot_control_functions.php.
if (!function_exists('start_bot_for_user')) {
    function start_bot_for_user($username, $botType = 'stable', $forceCustom = null)
    {
        global $conn, $api_key;
        // Load tokens and api_key for the user
        $stmt = $conn->prepare("SELECT id, twitch_user_id, access_token, refresh_token, api_key, use_custom, use_self, use_custom_module FROM users WHERE username = ? LIMIT 1");
        if (!$stmt)
            return ['success' => false, 'message' => t('admin_start_bots_err_db_token_lookup')];
        $stmt->bind_param('s', $username);
        $stmt->execute();
        $res = $stmt->get_result();
        $row = $res ? $res->fetch_assoc() : null;
        $stmt->close();
        if (!$row)
            return ['success' => false, 'message' => t('admin_start_bots_err_user_not_found')];
        // Extract all required fields
        $userId = trim((string) ($row['id'] ?? ''));
        $twitchUserId = trim($row['twitch_user_id'] ?? '');
        $accessToken = trim($row['access_token'] ?? '');
        $refreshToken = trim($row['refresh_token'] ?? '');
        $useCustom = ((int) ($row['use_custom'] ?? 0)) === 1;
        $useSelf = ((int) ($row['use_self'] ?? 0)) === 1;
        $useCustomModule = ((int) ($row['use_custom_module'] ?? 0)) === 1;
        // Get API key - try per-user key first, then global fallback
        $userApiKey = trim($row['api_key'] ?? '');
        $globalApiKey = trim($api_key ?? '');
        $finalApiKey = !empty($userApiKey) ? $userApiKey : $globalApiKey;
        // Validate all required parameters before proceeding
        $missingParams = [];
        if (empty($username))
            $missingParams[] = 'username';
        if (empty($twitchUserId))
            $missingParams[] = 'twitch_user_id';
        if (empty($accessToken))
            $missingParams[] = 'access_token';
        if (empty($refreshToken))
            $missingParams[] = 'refresh_token';
        if (empty($finalApiKey))
            $missingParams[] = 'api_key';
        if (!empty($missingParams)) {
            return [
                'success' => false,
                'message' => t('admin_start_bots_err_missing_params', [implode(', ', $missingParams)]),
                'debug_info' => [
                    'username' => $username,
                    'twitch_user_id' => !empty($twitchUserId) ? 'present' : 'MISSING',
                    'access_token' => !empty($accessToken) ? 'present' : 'MISSING',
                    'refresh_token' => !empty($refreshToken) ? 'present' : 'MISSING',
                    'api_key' => !empty($finalApiKey) ? 'present' : 'MISSING'
                ]
            ];
        }
        // If performBotAction exists, delegate to it with all required params
        if (function_exists('performBotAction')) {
            $mode = admin_start_mode_params($conn, $botType, $userId, $twitchUserId, $useCustom, $useSelf, $forceCustom);
            if (!empty($mode['_error'])) {
                return ['success' => false, 'message' => $mode['_error']];
            }
            $actionBotType = $mode['_action_bot_type'];
            unset($mode['_action_bot_type'], $mode['_error']);
            $params = array_merge([
                'username' => $username,
                'twitch_user_id' => $twitchUserId,
                'auth_token' => $accessToken,
                'refresh_token' => $refreshToken,
                'api_key' => $finalApiKey,
                'load_custom_module' => $useCustomModule,
            ], $mode);
            $res = performBotAction('run', $actionBotType, $params);
            // performBotAction returns an array
            return $res;
        }
        return ['success' => false, 'message' => t('admin_start_bots_err_no_impl')];
    }
}

// Check for AJAX requests IMMEDIATELY - before any other includes
if ($_SERVER['REQUEST_METHOD'] === 'GET' && isset($_GET['get_running_bots'])) {
    // Clean ALL output buffers
    while (ob_get_level()) {
        ob_end_clean();
    }
    // Release session lock so concurrent admin requests are not blocked while we
    // wait on the bots host (process scan can take several seconds).
    if (session_status() === PHP_SESSION_ACTIVE) {
        session_write_close();
    }
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    try {
        ob_start();
        // Lightweight client only - do not pull bot_control_functions (SSH config).
        require_once '/var/www/dashboard/includes/bots_api_client.php';
        $running_bots = [];
        $resp = bots_api_running_bots();
        if (!$resp['ok']) {
            $debug = ob_get_clean();
            $err = $resp['error'] ?? 'Bots API request failed';
            if (is_array($err)) {
                $err = json_encode($err);
            }
            echo json_encode([
                'success' => false,
                'message' => is_string($err) ? $err : 'Bots API request failed',
                'bots' => [],
                'snapshot' => null,
                'http_status' => (int) ($resp['status'] ?? 0),
                'debug' => $debug,
            ]);
            exit;
        }
        $data = is_array($resp['data']) ? $resp['data'] : [];
        // Support both shapes: { bots: { stable: [...] } } and accidental flat lists
        $buckets = $data['bots'] ?? null;
        if (!is_array($buckets)) {
            $buckets = [];
        }
        // Old/new API: keys are bot types; if a list was returned, ignore
        $isBucketMap = isset($buckets['stable']) || isset($buckets['beta']) || isset($buckets['v6']) || isset($buckets['custom']) || isset($buckets['kick']);
        if (!$isBucketMap && $buckets !== [] && array_keys($buckets) === range(0, count($buckets) - 1)) {
            $buckets = ['stable' => $buckets];
        }
        foreach (['stable', 'beta', 'v6', 'custom'] as $botType) {
            foreach ((array) ($buckets[$botType] ?? []) as $entry) {
                if (!is_array($entry)) {
                    continue;
                }
                $running_bots[] = [
                    'username' => strtolower(trim((string) ($entry['channel'] ?? ''))),
                    'pid' => (int) ($entry['pid'] ?? 0),
                    'bot_type' => $entry['bot_type'] ?? $botType,
                    'custom' => !empty($entry['custom']) || (($entry['bot_type'] ?? $botType) === 'custom'),
                    'version' => $entry['version'] ?? '',
                    'uptime_seconds' => isset($entry['uptime_seconds']) ? (int) $entry['uptime_seconds'] : null,
                    'uptime_human' => null,
                    'currently_running' => true,
                    'last_seen_at' => $data['scanned_at'] ?? null,
                    'last_seen_ago_seconds' => 0,
                    'expected' => true,
                ];
            }
        }

        // Durable snapshot: bots expected to be running but not in the live scan
        // (server crash, OOM, reboot). Admins use last_seen_ago for recovery.
        // Safe when bots API is older and has no snapshot field yet.
        $snap = is_array($data['snapshot'] ?? null) ? $data['snapshot'] : [];
        $missing = [];
        $liveUsernames = [];
        foreach ($running_bots as $rb) {
            if (!empty($rb['username'])) {
                $liveUsernames[$rb['username']] = true;
            }
        }
        foreach ((array) ($snap['missing'] ?? []) as $entry) {
            if (!is_array($entry)) {
                continue;
            }
            $uname = strtolower(trim((string) ($entry['channel'] ?? '')));
            if ($uname === '') {
                continue;
            }
            // Prefer live row if both somehow appear
            if (isset($liveUsernames[$uname])) {
                continue;
            }
            $ago = isset($entry['last_seen_ago_seconds']) ? (int) $entry['last_seen_ago_seconds'] : null;
            $missing[] = [
                'username' => $uname,
                'pid' => (int) ($entry['pid'] ?? 0),
                'bot_type' => $entry['bot_type'] ?? 'stable',
                'version' => $entry['version'] ?? '',
                'uptime_seconds' => null,
                'uptime_human' => null,
                'currently_running' => false,
                'last_seen_at' => $entry['last_seen_at'] ?? null,
                'last_seen_ago_seconds' => $ago,
                'expected' => true,
                'was_running' => true,
            ];
        }

        $snapshotOut = [
            'updated_at' => $snap['updated_at'] ?? ($data['scanned_at'] ?? null),
            'expected_total' => (int) ($snap['expected_total'] ?? count($running_bots)),
            'live_total' => (int) ($snap['live_total'] ?? count($running_bots)),
            'missing_total' => (int) ($snap['missing_total'] ?? count($missing)),
            'missing' => $missing,
        ];

        $debug = ob_get_clean();
        $jsonFlags = 0;
        if (defined('JSON_INVALID_UTF8_SUBSTITUTE')) {
            $jsonFlags |= JSON_INVALID_UTF8_SUBSTITUTE;
        }
        echo json_encode([
            'success' => true,
            'bots' => $running_bots,
            'snapshot' => $snapshotOut,
            'scanned_at' => $data['scanned_at'] ?? null,
            'debug' => $debug,
        ], $jsonFlags);
    } catch (Throwable $e) {
        if (ob_get_level()) {
            ob_end_clean();
        }
        echo json_encode([
            'success' => false,
            'message' => 'Error: ' . $e->getMessage(),
            'bots' => [],
            'snapshot' => null,
        ]);
    }
    exit;
}

// Lightweight single-bot status check (used by Restart All to verify ONE bot without
// re-scanning every user). One bots-API status call, filtered to this channel.
if ($_SERVER['REQUEST_METHOD'] === 'GET' && isset($_GET['check_one_bot'])) {
    while (ob_get_level()) {
        ob_end_clean();
    }
    header('Content-Type: application/json');
    try {
        require_once '/var/www/dashboard/includes/bot_control_functions.php';
        $uname = trim($_GET['username'] ?? '');
        $botType = trim($_GET['bot_type'] ?? 'stable');
        if ($uname === '') {
            echo json_encode(['success' => false, 'message' => 'Missing username', 'pid' => 0]);
            exit;
        }
        // checkBotRunning() tries the bots control API first, falling back to an SSH
        // ps scan only if the API is unreachable - same pattern as start/stop.
        $status = checkBotRunning($uname, $botType);
        echo json_encode([
            'success' => true,
            'running' => $status['running'],
            'pid' => $status['pid'],
            'bot_type' => $botType
        ]);
    } catch (Exception $e) {
        echo json_encode(['success' => false, 'message' => 'Error: ' . $e->getMessage(), 'pid' => 0]);
    }
    exit;
}

// Handle AJAX request to validate a user's token
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['validate_user_token'])) {
    // Clean any output that may have been generated
    ob_end_clean();
    header('Content-Type: application/json');
    try {
        // Clean any output that may have been generated and capture incidental output
        while (ob_get_level())
            ob_end_clean();
        ob_start();
        $twitch_user_id = $_POST['twitch_user_id'] ?? '';
        if (empty($twitch_user_id)) {
            echo json_encode(['success' => false, 'message' => 'Missing twitch_user_id']);
            exit;
        }
        $cacheEntry = getTokenCacheEntry($tokenCacheFile, $twitch_user_id);
        if (
            $cacheEntry
            && !empty($cacheEntry['login_expires_at']) && $cacheEntry['login_expires_at'] > time()
            && !empty($cacheEntry['bot_expires_at']) && $cacheEntry['bot_expires_at'] > time()
            && !empty($cacheEntry['is_mod'])
        ) {
            $expires_in = min(
                (int) $cacheEntry['login_expires_at'] - time(),
                (int) $cacheEntry['bot_expires_at'] - time()
            );
            $is_mod = $cacheEntry['is_mod'] ?? false;
            $debug = ob_get_clean();
            echo json_encode([
                'success' => true,
                'valid' => true,
                'expires_in' => $expires_in,
                'is_mod' => $is_mod,
                'login_valid' => true,
                'bot_valid' => true,
                'message' => t('admin_start_bots_token_both_valid'),
                'debug' => $debug
            ]);
            exit;
        }
        $ensured = admin_start_bots_ensure_token_pair($conn, $twitch_user_id, $clientID ?? '', $clientSecret ?? '');
        if (!empty($ensured['ok'])) {
            $access_token = $ensured['bot_token'] !== '' ? $ensured['bot_token'] : $ensured['login_token'];
            $expires = (int) ($ensured['expires_in'] ?? 0);
            // Mod/API checks use the bot token, not the login/start token
            $bot_user_id = '971436498';
            $mod_url = "https://api.twitch.tv/helix/moderation/moderators?broadcaster_id={$twitch_user_id}&user_id={$bot_user_id}";
            $mod_headers = [
                "Authorization: Bearer {$access_token}",
                "Client-Id: {$clientID}"
            ];
            $mod_ch = curl_init();
            curl_setopt($mod_ch, CURLOPT_URL, $mod_url);
            curl_setopt($mod_ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($mod_ch, CURLOPT_HTTPHEADER, $mod_headers);
            $mod_response = curl_exec($mod_ch);
            $mod_httpCode = curl_getinfo($mod_ch, CURLINFO_HTTP_CODE);
$is_mod = false;
            $is_banned = false;
            $ban_reason = '';
            if ($mod_httpCode === 200) {
                $mod_data = json_decode($mod_response, true);
                $is_mod = !empty($mod_data['data']);
                // If NOT a mod, check if bot is banned
                if (!$is_mod) {
                    $ban_url = "https://api.twitch.tv/helix/moderation/banned?broadcaster_id={$twitch_user_id}&user_id={$bot_user_id}";
                    $ban_ch = curl_init();
                    curl_setopt($ban_ch, CURLOPT_URL, $ban_url);
                    curl_setopt($ban_ch, CURLOPT_RETURNTRANSFER, true);
                    curl_setopt($ban_ch, CURLOPT_HTTPHEADER, $mod_headers);
                    $ban_response = curl_exec($ban_ch);
                    $ban_httpCode = curl_getinfo($ban_ch, CURLINFO_HTTP_CODE);
if ($ban_httpCode === 200) {
                        $ban_data = json_decode($ban_response, true);
                        if (!empty($ban_data['data'])) {
                            $is_banned = true;
                            $ban_reason = $ban_data['data'][0]['reason'] ?? 'No reason provided';
                        }
                    }
                }
            }
            if ($expires > 0) {
                $entry = [
                    'login_expires_at' => time() + (int) ($ensured['login_expires_in'] ?? $expires),
                    'bot_expires_at' => time() + (int) ($ensured['bot_expires_in'] ?? $expires),
                    'expires_at' => time() + $expires,
                    'is_mod' => $is_mod,
                    'repaired' => $ensured['repaired'] ?? [],
                ];
                @setTokenCacheEntry($tokenCacheFile, $twitch_user_id, $entry);
            }
            $debug = ob_get_clean();
            echo json_encode([
                'success' => true,
                'valid' => true,
                'expires_in' => $expires,
                'is_mod' => $is_mod,
                'is_banned' => $is_banned,
                'ban_reason' => $ban_reason,
                'login_valid' => true,
                'bot_valid' => true,
                'repaired' => $ensured['repaired'] ?? [],
                'message' => $ensured['message'],
                'debug' => $debug
            ]);
        } else {
            @removeTokenCacheEntry($tokenCacheFile, $twitch_user_id);
            $debug = ob_get_clean();
            echo json_encode([
                'success' => true,
                'valid' => false,
                'login_valid' => !empty($ensured['login_valid']),
                'bot_valid' => !empty($ensured['bot_valid']),
                'message' => $ensured['message'] ?? t('admin_start_bots_token_both_invalid'),
                'debug' => $debug
            ]);
        }
    } catch (Exception $e) {
        $debug = ob_get_clean();
        echo json_encode(['success' => false, 'message' => 'Error: ' . $e->getMessage(), 'debug' => $debug]);
    }
    exit;
}

